function validate(input) {
  const [fn, obj, inputs] = input;
  const names = ['multiply', 'speak', 'sum', 'greet', 'pick', 'countArgs', 'countKeys'];
  if (!names.includes(fn)) return `fn must be one of ${names.join(', ')}.`;
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) return 'obj must be a JSON object.';
  if (Object.hasOwn(obj, '__proto__')) return 'obj may not have a key named "__proto__".';
  if (!Array.isArray(inputs) || inputs.length > 100) return 'inputs must be a list of at most 100 values.';
  const number = value => typeof value === 'number';
  const string = value => typeof value === 'string';
  const shape = (key, test, count, each) => test(obj[key]) && inputs.length === count && inputs.every(each);
  if (fn === 'multiply' && !shape('x', number, 1, number)) return 'multiply needs a number "x" in obj and one number in inputs.';
  if (fn === 'speak' && !shape('name', string, 0, string)) return 'speak needs a string "name" in obj and no inputs.';
  if (fn === 'sum' && !shape('base', number, inputs.length, number)) return 'sum needs a number "base" in obj and only numbers in inputs.';
  if (fn === 'greet' && !shape('name', string, 2, string)) return 'greet needs a string "name" in obj and two strings in inputs.';
  if (fn === 'pick' && !(inputs.length === 1 && string(inputs[0]))) return 'pick takes one string, the key to read.';
  if (fn === 'countKeys' && inputs.length !== 0) return 'countKeys takes no inputs.';
  return null;
}

