function adapt(input, solve, kit) {
  const [name, obj, inputs] = input;
  const show = value => { try { return JSON.stringify(value) ?? String(value); } catch { return String(value); } };
  const ran = (self, values) => kit.trace(`${name} runs with this = ${show(self)} and arguments ${show(values)}`);
  // The functions a case can name. Each one reports the this and the arguments it received.
  const library = {
    multiply: function multiply(multiplier) { ran(this, [multiplier]); return this.x * multiplier; },
    speak: function speak() { ran(this, []); return 'My name is ' + this.name; },
    sum: function sum(...nums) { ran(this, nums); return nums.reduce((total, x) => total + x, this.base); },
    greet: function greet(greeting, mark) { ran(this, [greeting, mark]); return `${greeting}, ${this.name}${mark}`; },
    pick: function pick(key) { ran(this, [key]); return Object.hasOwn(this, key) ? this[key] : null; },
    countArgs: function countArgs(...values) { ran(this, values); return values.length; },
    countKeys: function countKeys() { ran(this, []); return Object.keys(this).length; },
  };
  const fn = library[name];
  if (typeof fn.bindPolyfill !== 'function') throw new Error('Functions have no bindPolyfill method yet: assign a function to Function.prototype.bindPolyfill.');
  const bind = Function.prototype.bind;
  Function.prototype.bind = function () { throw new Error('Solve it without Function.prototype.bind.'); };
  let result;
  try {
    kit.trace(`${name}.bindPolyfill(${show(obj)}) is called`);
    const boundFunc = fn.bindPolyfill(obj);
    if (typeof boundFunc !== 'function') throw new Error('bindPolyfill must return a function.');
    kit.trace(`boundFunc(${inputs.map(show).join(', ')}) is called`);
    result = boundFunc(...inputs);
  } finally {
    Function.prototype.bind = bind;
  }
  if (result === undefined) throw new Error('The bound function returned undefined; return what the original function returns.');
  kit.trace(`boundFunc returns ${show(result)}`);
  return result;
}

