function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const words = ['Kathy', 'Ada', 'Lin', 'x', ''];
  const primitive = () => {
    const roll = rand();
    if (roll < 0.4) return int(-50, 50);
    if (roll < 0.7) return pick(words);
    if (roll < 0.85) return rand() < 0.5;
    return null;
  };
  // Unrelated keys in obj, which the function must still see.
  const obj = {};
  const extra = small ? int(0, 2) : 300;
  for (let i = 0; i < extra; i++) obj[pick(['k', 'id', 'v', 'tag']) + i] = rand() < 0.2 ? [primitive(), { inner: primitive() }] : primitive();
  const name = pick(['multiply', 'speak', 'sum', 'greet', 'pick', 'countArgs', 'countKeys']);
  let inputs = [];
  if (name === 'multiply') {
    obj.x = int(-100, 100);
    inputs = [rand() < 0.2 ? pick([0.5, 1.5, -0.25]) : int(-20, 20)];
  } else if (name === 'speak') {
    obj.name = pick(words);
  } else if (name === 'sum') {
    obj.base = int(-50, 50);
    inputs = Array.from({ length: small ? int(0, 4) : 100 }, () => int(-1000, 1000));
  } else if (name === 'greet') {
    obj.name = pick(words);
    inputs = [pick(['Hello', 'Hi', 'Hey']), pick(['!', '.', '?', ''])];
  } else if (name === 'pick') {
    const keys = Object.keys(obj);
    inputs = [keys.length && rand() < 0.7 ? pick(keys) : pick(['missing', 'toString', 'name'])];
  } else if (name === 'countArgs') {
    inputs = Array.from({ length: small ? int(0, 4) : 100 }, primitive);
  }
  return [name, obj, inputs];
}
